{"command":"cat > Tests/MessageTests.swift <<'EOF'
import XCTest

final class MessageTests: XCTestCase {
    func testSendStandupMessage() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))

        if !app.textViews["GrowingTextView"].exists {
            let room = app.staticTexts["Team Standup"].firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 10), "Team Standup room not visible")
            room.tap()
        }

        let composer = app.textViews["GrowingTextView"]
        XCTAssertTrue(composer.waitForExistence(timeout: 10), "Message composer not found")
        composer.tap()
        composer.typeText("good morning")

        let sendButton = app.buttons["SendButton"]
        XCTAssertTrue(sendButton.waitForExistence(timeout: 5), "Send button not found")
        XCTAssertTrue(sendButton.isEnabled, "Send button remained disabled")
        sendButton.tap()

        XCTAssertTrue(app.staticTexts["good morning"].waitForExistence(timeout: 10), "Sent message not visible")
        print("Verified 'good morning' in Team Standup")
    }
}
EOF
